from collections import deque

graph = {'S': ['A', 'B'], 'A': ['C'], 'B': ['D'], 'C': ['G'], 'D': ['G'], 'G': []}

def bfs(graph, start, goal):
    queue = deque([(start, [start])])
    while queue:
        node, path = queue.popleft()
        if node == goal:
            return path
        for nxt in graph[node]:
            queue.append((nxt, path + [nxt]))
    return None

print(bfs(graph, 'S', 'G'))
